      SUBROUTINE RDIND(FLAG)C---- READ INDICATOR CARD WITH POSSIBLE KEYWORDS C---------------------------------------------------------------------      LOGICAL         FLAGC---------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'NPLIN.CIN'      INCLUDE 'OUTFIL.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARVAL.CIN'      INCLUDE 'PRINTC.CIN'      INCLUDE 'PRINTL.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'RDCOMS.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'C ---------------------------------------------------------------------      CHARACTER*15    DIND(16)C      DATA NIND /16/      DATA DIND( 1) /'INDICATO'/      DATA DIND( 2) /'NORAYS'/      DATA DIND( 3) /'NOLIST'/      DATA DIND( 4) /'REFORMAT'/      DATA DIND( 5) /'NOBEFORE'/      DATA DIND( 6) /'NOPRINT'/      DATA DIND( 7) /'NOSOLVE'/      DATA DIND( 8) /'BWRITE'/      DATA DIND( 9) /'BREAD'/      DATA DIND(10) /'PRINT'/      DATA DIND(11) /'MAD'/      DATA DIND(12) /'TRANSPORT'/      DATA DIND(13) /'LATDEF'/      DATA DIND(14) /'STRUCT'/      DATA DIND(15) /'ACAD'/      DATA DIND(16) /'FILE'/C      DO 30 J = 1, MAXPAR      IPTYP(J) = 0      IPDAT(J) = 0      IOPERS(J) = 0   30 PDATA(J) = 0.0      FLAG = .TRUE.      NCOMS = 0   40 CALL RDNEXT      IF (ENDFIL) GO TO 100      IF (ITEM .EQ. SEMI .OR. ITEM .EQ. ASTER .OR. ITEM .EQ. DOLLAR)     1    GO TO 40      IF (ITEM .NE. PARENO) GO TO 50      NCOMS = NCOMS + 1      CALL RDSTRG(CMMNT,78,L)      LCOM = L      IF (L .EQ. -1) GO TO 50      GO TO 40C   50 IF (INDEX(NUMB,ITEM) .EQ. 0) GO TO 100      FLAG = .FALSE.      CALL RDBACK      NTYPE = 0      OUTFIL = ' '      LOUTF = 0      CALL DECPAR(NIND,DIND,2,NPLIN,NIND)      IF (ENDFIL) GO TO 100      IF (IPTYP(1) .NE. 0) INDIC = INT(PDATA(1))      IF (IPTYP(2) .EQ. 0) NORAYS = INT(PDATA(1))      IF (IPTYP(2) .NE. 0) NORAYS = INT(PDATA(2))      IF (IPTYP(3) .EQ. -2) LIST = .FALSE.      IF (IPTYP(4) .EQ. -2) RFM = .TRUE.      IF (IPTYP(5) .EQ. -2) BEF = .FALSE.      IF (IPTYP(6) .EQ. -2) PRNT = .FALSE.      IF (IPTYP(7) .EQ. -2) SLV = .FALSE.      IF (IPTYP(8) .EQ. -2) BWT = .TRUE.      IF (IPTYP(9) .EQ. -2) BRD = .TRUE.      IF (.NOT. SLV) PRNT = .FALSE.      IF (.NOT. PRNT) BEF = .FALSE.C      IF (IPTYP(10) .EQ. -2 .AND. IPTYP(11) .EQ. -2) THEN        MADL = .TRUE.        MADFILE = OUTFIL        LMADF = LOUTF      ENDIFC      IF (IPTYP(10) .EQ. -2 .AND. IPTYP(12) .EQ. -2) THEN        TRANSPORTL = .TRUE.        TRANSPORTFILE = OUTFIL        LTRANSPORTF = LOUTF      ENDIFC      IF (IPTYP(10) .EQ. -2 .AND. IPTYP(13) .EQ. -2) THEN        LATDEFL = .TRUE.        LATDEFFILE = OUTFIL        LLATDEFF = LOUTF      ENDIFC      IF (IPTYP(10) .EQ. -2 .AND. IPTYP(14) .EQ. -2) THEN        STRUCTL = .TRUE.        STRUCTFILE = OUTFIL        LSTRUCTF = LOUTF      ENDIFC      IF (IPTYP(10) .EQ. -2 .AND. IPTYP(15) .EQ. -2) THEN        ACADL = .TRUE.        ACADFILE = OUTFIL        LACADF = LOUTF      ENDIFC      IF (IPTYP(10) .EQ. -2 .AND. IPTYP(16) .EQ. -2) THEN        FILEL = .TRUE.      ENDIFC      INDS = MOD(INDIC,10)      INDP = MOD(INDIC/10,10)      IF (INDP .NE. 0) LIST = .FALSE.  100 CONTINUE      RETURN      END